import React, { useRef, useEffect } from 'react';
import { CalendarEvent } from '../types';

interface EventCardProps {
  event: CalendarEvent;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onRenderRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

const categoryBorderColors: Record<string, string> = {
  Meeting: '#60a5fa',
  Deadline: '#f43f5e',
  'Focus block': '#34d399',
  Personal: '#fbbf24'
};

const RawEventCard: React.FC<EventCardProps> = ({
  event,
  onDragStart,
  onRenderRecord,
  onDelete
}) => {
  useEffect(() => {
    onRenderRecord(event.id);
  });

  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, event.id)}
      style={{
        borderLeft: `3px solid ${categoryBorderColors[event.category] || '#60a5fa'}`,
        backgroundColor: '#131b2e',
        borderTop: '1px solid #1e293b',
        borderRight: '1px solid #1e293b',
        borderBottom: '1px solid #1e293b'
      }}
      className="group relative p-2.5 rounded shadow-sm hover:brightness-110 cursor-grab active:cursor-grabbing select-none text-left mb-2 transition-all"
    >
      <div className="flex justify-between items-center mb-0.5">
        <span className="text-[11px] font-mono text-slate-400">
          {event.time}
        </span>
        <button
          onClick={(e) => {
            e.stopPropagation();
            onDelete(event.id);
          }}
          className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-rose-400 text-xs px-1"
          title="Delete event"
        >
          ×
        </button>
      </div>
      <h4 className="text-xs font-semibold text-slate-100 truncate">
        {event.title}
      </h4>
    </div>
  );
};

export const MemoizedEventCard = React.memo(RawEventCard);
export const UnmemoizedEventCard = RawEventCard;
